function lastMetricType(items=[],known=['weight','pressure','glucose','sleep','heart']){const t=newest(items.filter(i=>i.kind==='metric'))?.type;return known.includes(t)?t:'weight';}
// Blood pressure: systolic is complete after 3 digits when it starts with 1–2 (100–299), otherwise after 2 digits (30–99).
function systolicComplete(value){const v=String(value??'').trim();if(!/^\d+$/.test(v))return false;return /^[12]/.test(v)?v.length>=3:v.length>=2;}
return { mealTypeForHour, shanghaiHour, exerciseDefaults, lastMetricType, systolicComplete };
