 function tabs(){return `<div class="medical-view-tabs">${[['visits','全部就诊',all('visit').length],['medications','用药管理',all('medication').length],['reports','就诊报告',all('report').length]].map(([v,l,n])=>`<button class="${view===v?'active':''}" data-action="med-view:${v}">${l}<span>${n}</span></button>`).join('')}</div>`}
 function render(){const route=location.hash.split('/')[1];activeId=route&&find(route)?.kind==='visit'?route:null;if(route&&!activeId)return `<div class="card">${panelEmpty('visit','找不到这次就诊','记录可能已被移除，关联资料仍可从就医管理中查找。','med-view:visits','返回就医管理')}</div>`;if(activeId)return detail(find(activeId));return `${tabs()}<div class="filters"><div class="searchbox">${icon('search',15)}<input id="medical-search" aria-label="搜索就医内容" placeholder="搜索${view==='visits'?'就诊、医院或科室':view==='medications'?'药名或用药备注':'报告标题或来源'}…" value="${esc(search)}"></div><div class="medical-filter-tools">${view==='medications'?`<input id="med-dose-date" class="filter-input" type="date" value="${doseDate||ctx.today}" max="${ctx.today}" aria-label="查看用药日期">`:''}${view==='visits'?`<select id="medical-status" class="filter-input" aria-label="就诊状态"><option value="all">全部状态</option>${['待就诊','已完成','待复查'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select>`:''}${view==='visits'?'':btn(view==='medications'?'添加用药方案':'添加报告',view==='medications'?'med-new-medication':'med-new-report','primary','plus')}</div></div><div id="medical-list">${listContent()}</div>`}
 function listContent(){if(view==='visits'){const vs=sort(all('visit')).filter(x=>(status==='all'||x.status===status)&&`${x.title} ${x.hospital||''} ${x.department||''}`.includes(search));return `<div class="visit-cards minimal-visit-list">${vs.length?vs.map(v=>{const n=k=>all(k).filter(x=>x.visitId===v.id).length;return `<article class="visit-row"><div class="visit-row-main"><button class="visit-card-title" data-action="med-open:${v.id}">${esc(v.title)}</button>${aiTag(v)}<p class="visit-card-meta">${esc(v.hospital||'机构待补充')} · ${esc(v.department||'科室待补充')}${v.doctor?' · '+esc(v.doctor):''}</p><p class="visit-reason">${esc(v.reason||v.note||'暂无就诊备注')}</p></div><div class="visit-row-context"><time>${v.date}${v.time?' · '+esc(v.time):''}</time>${badge(v.status,'visit')}<div class="visit-card-counts"><span>报告 ${n('report')}</span><span>用药 ${n('medication')}</span><span>待办 ${all('task').filter(x=>x.visitId===v.id&&!x.done).length}</span></div></div><div class="visit-row-actions"><button class="icon-btn" data-action="med-open:${v.id}" aria-label="查看${esc(v.title)}详情">${icon('arrow',17)}</button>${actions(v)}</div></article>`}).join(''):panelEmpty('visit',search||status!=='all'?'没有匹配的就诊':'从一次就诊开始','在一次就诊中整理报告、用药和复查安排。','add:visit','添加就诊')}</div>`}
 if(view==='medications'){const meds=sort(all('medication')).filter(x=>`${x.title} ${x.note||''}`.includes(search));return meds.length?`<div class="medication-list">${meds.map(m=>medicationCard(m)).join('')}</div>`:`<div class="card">${panelEmpty('heart','还没有用药方案','按医生处方录入方案，再记录每次服用。','med-new-medication','添加用药方案')}</div>`;}
 const reports=sort(all('report')).filter(x=>`${x.title} ${x.source||''} ${x.content||''}`.includes(search));return `<section class="card">${reports.length?`<div class="record-list">${reports.map(r=>reportRow(r,true)).join('')}</div>`:panelEmpty('file','还没有就诊报告','可录入报告原文，并上传或关联原始文件。','med-new-report','添加报告')}</section>`;}
 function detail(v){const reports=sort(all('report').filter(x=>x.visitId===v.id)),meds=sort(all('medication').filter(x=>x.visitId===v.id)),tasks=sort(all('task').filter(x=>x.visitId===v.id)),files=sort(all('file').filter(x=>x.visitId===v.id));
 return `<button class="text-btn medical-back" data-action="med-view:visits">← 返回就医管理</button><section class="card visit-hero"><div class="visit-hero-top"><span class="event-icon visit">${icon('visit',24)}</span><div class="visit-hero-info"><div class="visit-detail-date">${v.date}</div><h1>${esc(v.title)}${aiTag(v)}</h1><p>${esc(v.hospital||'机构待补充')} · ${esc(v.department||'科室待补充')}${v.doctor?' · '+esc(v.doctor):''}${v.time?' · '+esc(v.time):''}</p></div>${badge(v.status,'visit')}${btn('编辑就诊','edit:'+v.id,'','edit')}</div><div class="visit-hero-stats"><span>${reports.length} 份报告</span><span>${meds.filter(m=>m.status==='进行中').length} 个进行中的用药方案</span><span>${tasks.filter(t=>!t.done).length} 项待跟进</span><span>${files.length} 份原件</span></div></section><div class="medical-detail-tabs">${[['overview','就诊概览'],['reports','就诊报告'],['medications','用药与服用记录'],['followup','复查与待办']].map(([k,l])=>`<button class="${section===k?'active':''}" data-action="med-section:${k}">${l}</button>`).join('')}</div>${section==='overview'?`<div class="visit-overview-grid"><div>${card('就诊记录','',btn('编辑记录','edit:'+v.id,'','edit'),`<div class="clinical-notes">${[['就诊原因 / 主诉',v.reason],['医生记录 / 结论原文',v.assessment],['医嘱与注意事项',v.instructions],['其他记录（含原有备注）',v.note]].map(([l,c])=>`<div class="clinical-note"><h3>${l}</h3><p class="${!c?'muted':''}">${esc(c||'尚未补充，可按原始记录录入。')}</p></div>`).join('')}</div>`)}${card('就诊报告',reports.length,titleAction('添加报告','med-new-report:'+v.id),reports.length?`<div class="record-list">${reports.slice(0,3).map(r=>reportRow(r)).join('')}</div>`:panelEmpty('file','整理这次就诊的报告','保存就诊记录、检验、影像或处方原文。','med-new-report:'+v.id,'添加报告'))}</div><div>${card('用药方案',meds.length,titleAction('添加方案','med-new-medication:'+v.id),meds.length?`<div class="compact-med-list">${meds.map(m=>`<button class="compact-med" data-action="med-section:medications"><span>${icon('heart',16)}</span><div><strong>${esc(m.title)}</strong>${aiTag(m)}<small>${esc(m.dosage)} · ${esc(m.frequency)}</small></div>${badge(m.status)}</button>`).join('')}</div>`:panelEmpty('heart','暂无用药方案','按处方记录药物、用量与频次。','med-new-medication:'+v.id,'添加用药方案'))}${followupCard(tasks,v.id)}${filesCard(files,v.id)}</div></div>`:section==='reports'?`${card('本次就诊报告',reports.length,titleAction('添加报告','med-new-report:'+v.id),reports.length?`<div class="record-list">${reports.map(r=>reportRow(r)).join('')}</div>`:panelEmpty('file','尚未添加报告','可以先建立待出报告的记录，拿到原件后再补充。','med-new-report:'+v.id,'添加报告'))}${filesCard(files,v.id)}`:section==='medications'?`<div class="medical-section-heading"><p>方案按处方录入；服用记录可更正，不生成用药建议。</p><div>${field('查看服用日期','doseDate',doseDate||ctx.today,'date',`max="${ctx.today}"`)}${btn('添加用药方案','med-new-medication:'+v.id,'primary','plus')}</div></div>${meds.length?meds.map(m=>medicationCard(m)).join(''):`<div class="card">${panelEmpty('heart','这次就诊还没有用药方案','请按处方填写，不由系统推断用量。','med-new-medication:'+v.id,'添加用药方案')}</div>`}`:followupCard(tasks,v.id)}`;
 }
 function followupCard(tasks,visitId){return card('复查与后续事项',tasks.filter(x=>!x.done).length+' 项待完成',titleAction('添加事项','med-new-task:'+visitId),tasks.length?`<div class="record-list">${tasks.map(t=>`<div class="task-row"><button class="check ${t.done?'checked':''}" data-action="toggle:${t.id}" aria-pressed="${t.done}" aria-label="${t.done?'取消完成':'完成'}：${esc(t.title)}">${t.done?icon('check',12):''}</button><div class="task-copy"><strong>${esc(t.title)}</strong><small>${t.date} ${esc(t.time||'')} · ${t.done?'已完成':'待完成'}</small>${t.note?`<p class="medical-task-note">${esc(t.note)}</p>`:''}</div>${actions(t)}</div>`).join('')}</div>`:panelEmpty('calendar','把后续安排放在这里','复查、预约或需要准备的资料，都可以建立待办。','med-new-task:'+visitId,'添加复查事项'));}
 function filesCard(files,id){return card('原始资料',files.length,titleAction('上传资料','med-upload:'+id),files.length?`<div class="record-list">${files.map(f=>`<div class="record medical-file-row"><span class="event-icon">${icon('file',18)}</span><div class="record-info"><button class="link-title" data-action="med-preview:${f.id}">${esc(f.title)}</button><p>${f.date} · ${Math.ceil(f.size/1024)} KB</p></div>${btn('预览','med-preview:'+f.id)}<a class="icon-btn" aria-label="下载${esc(f.title)}" href="/api/files/${f.id}?space=${ctx.space}&workbench=${ctx.workbench}" download>${icon('download',16)}</a></div>`).join('')}</div>`:panelEmpty('file','还没有原件','支持 PDF、图片和 TXT；不会自动解析内容。','med-upload:'+id,'上传原件'));}
 function reportRow(r,showVisit=false){const f=find(r.fileId);return `<article class="record report-row"><span class="event-icon visit">${icon('file',19)}</span><div class="record-info"><button class="link-title" data-action="med-report:${r.id}">${esc(r.title)}</button>${aiTag(r)}<p>${r.date} · ${esc(r.type)}${r.source?' · '+esc(r.source):''}</p><div class="report-flags">${badge(r.status,'visit')}${badge(r.content?'已录文字':'文字待补充')}${badge(f?'已关联原件':'原件待补充',f?'':'neutral')}</div>${showVisit?visitLink(r.visitId):''}</div>${actions(r,`<button class="icon-btn" data-action="med-report:${r.id}" aria-label="查看报告${esc(r.title)}">${icon('arrow',15)}</button>`)}</article>`;}
 function medicationCard(m){const date=doseDate||ctx.today,logs=sort(all('dose').filter(d=>d.medicationId===m.id)),active=m.status==='进行中'&&m.date<=date&&(!m.endDate||m.endDate>=date),canLog=date<=ctx.today;const times=m.scheduleMode==='asNeeded'?[]:m.times||[];return `<section class="card medication-card"><div class="medication-head"><span class="event-icon metric">${icon('heart',21)}</span><div><h3>${esc(m.title)}</h3>${aiTag(m)}<p>${esc(m.prescriber||'处方来源待补充')} · ${m.date} 至 ${m.endDate||'未指定结束日期'}</p>${visitLink(m.visitId)}</div>${badge(m.status,m.status==='进行中'?'':'neutral')}${actions(m,m.status==='进行中'?`<button class="btn" data-action="med-status:${m.id}">停用方案</button>`:'')}</div><div class="medication-facts"><div><small>单次用量（按原处方）</small><strong>${esc(m.dosage)}</strong></div><div><small>用药途径</small><strong>${esc(m.route)}</strong></div><div><small>频次 / 用法</small><strong>${esc(m.frequency)}</strong></div><div><small>服用安排</small><strong>${m.scheduleMode==='asNeeded'?'按需记录':times.map(esc).join(' / ')}</strong></div></div>${m.note?`<div class="medication-note">${esc(m.note)}</div>`:''}<div class="dose-area"><div class="dose-heading"><strong>${date} · 服用记录</strong>${btn('补记一次服用','med-dose:'+m.id,'','plus')}</div>${active&&times.length?times.map(time=>{const d=logs.find(d=>d.date===date&&d.scheduledTime===time);return `<div class="dose-row"><span class="dose-time">${time}</span><span class="dose-outcome ${d?.outcome==='已服用'?'taken':''}">${d?esc(d.outcome)+(d.time?' · 实际 '+esc(d.time):''):'待记录'}</span>${d?aiTag(d):''}${d?`<button class="text-btn" data-action="med-edit:${d.id}">更正记录 ${icon('edit',12)}</button>`:canLog?`<div class="dose-actions"><button class="btn" data-action="med-take:${m.id}" data-time="${time}">记录服用</button><button class="text-btn" data-action="med-skip:${m.id}" data-time="${time}">跳过</button></div>`:''}</div>`}).join(''):`<p class="muted dose-explanation">${m.scheduleMode==='asNeeded'?'按需用药不预设次数，实际使用后记录。':m.status!=='进行中'?'方案已结束或停用，不再生成待服事项，历史记录仍保留。':'所选日期不在方案起止范围内。'}</p>`}</div><details class="dose-history"><summary>全部服用历史 <span>${logs.length} 条</span></summary>${logs.length?logs.map(d=>`<div class="dose-row"><div><strong>${d.date} ${esc(d.scheduledTime||'补记')}</strong>${aiTag(d)}<small>${esc(d.outcome)}${d.time?' · 实际 '+esc(d.time):''}${d.note?' · '+esc(d.note):''}</small></div>${actions(d)}</div>`).join(''):'<p class="muted">尚无服用记录。</p>'}</details></section>`;}
 function bind(){const input=document.querySelector('#medical-search');if(input)input.oninput=e=>{search=e.target.value;document.querySelector('#medical-list').innerHTML=listContent()};const statusEl=document.querySelector('#medical-status');if(statusEl)statusEl.onchange=e=>{status=e.target.value;document.querySelector('#medical-list').innerHTML=listContent()};for(const input of document.querySelectorAll('#med-dose-date,#field-doseDate'))input.onchange=e=>{doseDate=e.target.value||ctx.today;ctx.render()};}
 function openMedical(kind,id=null,visitId='',preset={}){const old=find(id);if(!old&&kind!=='dose'&&!all('visit').length){ctx.openDrawer(`<div class="medical-empty">${icon('visit',30)}<h3>先建立一次就诊</h3><p>报告和用药方案需要关联就诊，方便保留来源与后续安排。</p>${btn('添加就诊','add:visit','primary','plus')}</div>`,'关联就诊','先建立来源，再整理报告与用药');return;}const x={date:ctx.today,status:kind==='report'?'待补充':'进行中',type:'就诊记录',scheduleMode:'scheduled',times:[],...old,...preset};x.visitId=old?.visitId||visitId||x.visitId||activeId||'';let body='';
 if(kind==='report'){const files=all('file').filter(f=>!f.visitId||f.visitId===x.visitId);body=select('报告分类','type',['就诊记录','检验报告','影像报告','处方','出院记录','其他'],x.type)+select('报告状态','status',['待出报告','待补充','待核对','已归档'],x.status)+field('报告来源 / 机构','source',x.source||'','text','maxlength="250"')+textarea('报告原文 / 手工摘录','content',x.content||'','按原始报告逐字录入结论，不将推测写成检查事实。')+select('关联已有原件（可选）','fileId',[['','暂不关联'],...files.map(f=>[f.id,f.title])],x.fileId||'')+`<label class="upload-box">${icon('file',24)}<p>也可以上传一份新原件</p><input type="file" id="report-upload" accept=".pdf,.png,.jpg,.jpeg,.txt,.webp" aria-label="上传报告原件"><small>PDF、图片、TXT · 最大10MB · 不自动解析</small></label><div id="report-upload-state"></div>`;}
 if(kind==='medication')body=`<div class="helper">请按原始处方或医生交代填写。此处只记录方案，不推算用量。</div>`+field('单次用量（含单位）','dosage',x.dosage||'','text','required maxlength="250" placeholder="按处方原文填写"')+`<div class="form-grid">${field('用药途径','route',x.route||'','text','required maxlength="250" placeholder="按处方填写"')}${field('频次 / 用法','frequency',x.frequency||'','text','required maxlength="250" placeholder="按处方填写"')}</div>`+field('处方医生 / 来源','prescriber',x.prescriber||'','text','maxlength="250"')+select('记录方式','scheduleMode',[['scheduled','按指定时间记录'],['asNeeded','按需使用，不设次数']],x.scheduleMode)+`<div id="med-time-field" ${x.scheduleMode==='asNeeded'?'hidden':''}>${field('每日服用时间','times',(x.times||[]).join(', '),'text','placeholder="例如 08:00, 20:00"')}<p class="section-desc">时间以逗号分隔，最多12个；只用于应用内记录，不发送系统提醒。</p></div>`+field('结束日期（可选）','endDate',x.endDate||'','date')+select('方案状态','status',['进行中','已停用','已完成'],x.status);
 if(kind==='dose'){const med=find(x.medicationId);if(!med){ctx.toast('找不到用药方案');return}body=`<div class="helper"><b>${esc(med.title)}</b><br>${esc(med.dosage)} · ${esc(med.frequency)}<br>${x.scheduledTime?'对应计划时段 '+esc(x.scheduledTime):'补记一次实际使用，不额外生成计划次数。'}</div><input type="hidden" name="medicationId" value="${med.id}"><input type="hidden" name="scheduledTime" value="${esc(x.scheduledTime||'')}">`+select('服用结果','outcome',['已服用','跳过'],x.outcome||'已服用')+field('实际服用时间（跳过时可留空）','time',x.time||new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}).format(new Date()),'time');}
 const label={report:'就诊报告',medication:'用药方案',dose:'服用记录'}[kind];
 const sourceSpace=ctx.space,sourceWorkbench=ctx.workbench;
 ctx.openDrawer(`<form id="medical-form"><div class="helper">${ctx.space==='demo'?'示例空间 · 虚构示例，不构成处方':'个人空间 · 按原始记录填写'}</div>${kind==='dose'?'':select('关联就诊','visitId',visitOptions(x.visitId),x.visitId)}${field(kind==='medication'?'药物名称':kind==='report'?'报告标题':'记录名称','title',x.title||'','text','required maxlength="120"')}${field(kind==='medication'?'开始日期':'记录日期','date',x.date,'date',kind==='dose'?`required max="${ctx.today}"`:'required')}${body}${textarea(kind==='dose'?'备注 / 跳过原因（跳过必填）':'补充备注','note',x.note||'')}<div id="medical-error" role="alert"></div></form>`,`${id?'编辑':'添加'}${label}`,`${ctx.space==='demo'?'示例空间':'个人空间'} · 保存后回到当前页面`,`${btn('取消','close')}<button type="submit" form="medical-form" class="btn primary">${icon('check',14)}保存${label}</button>`);
 document.querySelector('#field-scheduleMode')?.addEventListener('change',e=>{document.querySelector('#med-time-field').hidden=e.target.value==='asNeeded'});
 if(kind==='dose'){const outcome=document.querySelector('#field-outcome');const timeField=document.querySelector('#field-time').closest('.field');timeField.hidden=outcome.value==='跳过';outcome.onchange=()=>{timeField.hidden=outcome.value==='跳过'};}
 let uploaded=null;
 document.querySelector('#medical-form').onsubmit=async e=>{e.preventDefault();const submit=document.querySelector('.drawer-foot button[type=submit]');submit.disabled=true;try{if(ctx.space!==sourceSpace)throw Error('空间已切换，请重新打开表单');const data=Object.fromEntries(new FormData(e.target));if(kind==='medication')data.times=data.scheduleMode==='asNeeded'?[]:String(data.times||'').split(/[,，\s]+/).filter(Boolean);
 if(kind==='report'){const file=document.querySelector('#report-upload').files[0];if(file){if(file.size>10*1024*1024)throw Error('原件不能超过10MB');if(!uploaded){const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('文件读取失败'));reader.readAsDataURL(file)});uploaded=await ctx.api('/api/upload',{method:'POST',body:JSON.stringify({name:file.name,title:file.name,date:data.date,visitId:data.visitId,content})},sourceSpace,sourceWorkbench);document.querySelector('#report-upload-state').innerHTML=`<p class="notice">${esc(uploaded.title)} 已保存到资料档案，待关联本报告。</p>`;}data.fileId=uploaded.id;}}
 await ctx.api(id?'/api/items/'+id:'/api/items',{method:id?'PUT':'POST',body:JSON.stringify({...data,kind})},sourceSpace,sourceWorkbench);if(document.querySelector('#medical-form')===e.target)ctx.closeDrawer();await ctx.load();ctx.toast(label+'已保存到健康工作台');}catch(err){if(e.target.isConnected&&showFieldError(e.target,err))return;const errorTarget=document.querySelector('#medical-error');if(!errorTarget){ctx.toast(err.message);return;}errorTarget.innerHTML=`<div class="form-error">${esc(err.message)}</div>`}finally{submit.disabled=false}};
 if(kind==='report')document.querySelector('#report-upload').onchange=()=>{uploaded=null;document.querySelector('#report-upload-state').innerHTML=''};
 }
