function summary(){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6);const cutoff=d.toISOString().slice(0,10);const week=items.filter(x=>x.date>=cutoff&&x.date<=today);const exercise=week.filter(x=>x.kind==='exercise'),metrics=week.filter(x=>x.kind==='metric'),visits=week.filter(x=>x.kind==='visit'),meals=week.filter(x=>x.kind==='meal');const text=`${cutoff} 至 ${today}\n\n就医：${visits.length} 条记录\n运动：${exercise.length} 次，共 ${exercise.reduce((n,x)=>n+x.duration,0)} 分钟\n饮食：${meals.length} 条记录\n监测：${metrics.length} 条记录\n\n待完成计划：${byKind('task').filter(x=>!x.done).length} 项\n\n这是依据已保存数据生成的本地统计摘要，未调用 AI 模型，也不包含诊断判断。`;$('#summary-output').innerHTML=`<div class="summary-output"><b>本地记录摘要</b>\n${esc(text)}</div>`}
let toastTimer;function toast(message,actionLabel='',action=''){$('#toast').innerHTML=`<span>${esc(message)}</span>${['撤销','查看'].includes(actionLabel)?'<span class="toast-sep" aria-hidden="true">·</span>':''}${actionLabel?`<button data-action="${action}">${actionLabel}</button>`:''}`;$('#toast').style.display='flex';clearTimeout(toastTimer);placeToast();toastTimer=setTimeout(()=>$('#toast').style.display='none',actionLabel?4500:3500)}
